CREATE TABLE "public"."installers" (
  "installer_id"        bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "acc_number"          text,
  "is_active"           boolean                  NOT NULL DEFAULT true,
  "first_name"          text,
  "last_name"           text,
  "company_name"        text,
  "phone_number"        text,
  "wcb_number"          text,
  "has_first_aid"       boolean,
  "has_insurance"       boolean,
  "gst_number"          text,
  "street_address"      text,
  "city"                text,
  "zip_code"            text,
  "email"               text,
  "notes"               text,
  "created_at"          timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  "legacy_installer_id" text,
  "updated_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "auth_user_id"        uuid,
  "is_servicetech"      boolean                  NOT NULL DEFAULT false,
  CONSTRAINT "installers_auth_user_id_fkey" FOREIGN KEY (auth_user_id) REFERENCES auth.users(id) ON DELETE SET NULL,
  CONSTRAINT "installers_auth_user_id_key" UNIQUE (auth_user_id),
  CONSTRAINT "installers_pkey" PRIMARY KEY (installer_id)
);

ALTER TABLE "public"."installers"
  ENABLE ROW LEVEL SECURITY;

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON public.installers
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable delete for admin only" ON "public"."installers"
  FOR DELETE
  TO PUBLIC
  USING ((public.clerk_user_role() = 'admin'::text));

CREATE POLICY "Enable insert for installers" ON "public"."installers"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'installation'::text, 'service'::text])));

CREATE POLICY "Enable read access for authenticated users" ON "public"."installers"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for installers" ON "public"."installers"
  FOR UPDATE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'installation'::text, 'service'::text])));

REVOKE ALL ON SEQUENCE "public"."installers_installer_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."installers_installer_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."installers_installer_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."installers_installer_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."installers_installer_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."installers_installer_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."installers_installer_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."installers_installer_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."installers" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."installers" TO "service_role";

REVOKE ALL ON TABLE "public"."installers" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."installers" TO "postgres";
